{"path": "wordy.py", "content": """"Parse and evaluate simple math word problems."""

OPERATIONS = {
    "plus": lambda x, y: x + y,
    "minus": lambda x, y: x - y,
    "multiplied": lambda x, y: x * y,
    "divided": lambda x, y: int(x / y),
}


def _to_int(token):
    try:
        return int(token)
    except ValueError:
        return None


def answer(question):
    prefix = "What is"
    if not question.startswith(prefix):
        raise ValueError("unknown operation")

    body = question[len(prefix):].strip().rstrip("?").strip()
    body = body.replace("multiplied by", "multiplied").replace("divided by", "divided")
    tokens = body.split()

    # Any word that is neither a number nor a known operation is unsupported.
    for token in tokens:
        if _to_int(token) is None and token not in OPERATIONS:
            raise ValueError("unknown operation")

    if not tokens:
        raise ValueError("syntax error")

    result = _to_int(tokens[0])
    if result is None:
        raise ValueError("syntax error")

    index = 1
    while index < len(tokens):
        operation = tokens[index]
        if operation not in OPERATIONS or index + 1 >= len(tokens):
            raise ValueError("syntax error")
        operand = _to_int(tokens[index + 1])
        if operand is None:
            raise ValueError("syntax error")
        if operation == "divided" and operand == 0:
            raise ValueError("division by zero")
        result = OPERATIONS[operation](result, operand)
        index += 2

    return result
"}

